/**
 *  Bilan d'un import, pour l'interface (compteurs typés `u32` pour
 *  TypeScript, envoyés avec leur valeur exacte).
 */
export type ImportSummary = {
	/**  Photos ajoutées. */
	addedPhotos: number,
	/**  Vidéos ajoutées. */
	addedVideos: number,
	/**  Fichiers déjà au catalogue. */
	alreadyInCatalog: number,
	/**  Doublons ignorés. */
	duplicatesSkipped: number,
	/**  Fichiers ajoutés sans date EXIF (date du fichier utilisée). */
	withoutExifDate: number,
	/**  Fichiers ajoutés dont les métadonnées étaient illisibles. */
	unreadableMetadata: number,
	/**  Fichiers ajoutés avec des mots-clés trouvés dans leurs métadonnées. */
	withRecoveredKeywords: number,
	/**  Fichiers ajoutés dont les sources de métadonnées se contredisaient. */
	metadataConflicts: number,
	/**  Éléments illisibles, non importés. */
	unreadableCount: number,
	/**  Quelques éléments illisibles, pour aider l'utilisateur à les trouver. */
	unreadableExamples: string[],
	/**  Nom du modèle de métadonnées posé sur les fichiers ajoutés. */
	templateName: string | null,
	/**  Import par copie : dossier où les fichiers ont été rangés. */
	destination: string | null,
	/**  Import par copie : photos et vidéos qui n'ont pas pu être copiées. */
	copyFailedCount: number,
	/**  Quelques-unes de ces photos et vidéos. */
	copyFailedExamples: string[],
	/**  Import par copie : fichiers annexes (XMP, `.dop`) non copiés. */
	sidecarsNotCopiedCount: number,
	/**  Copie de sauvegarde : dossier où les originaux ont été copiés. */
	backupFolder: string | null,
	/**  Copie de sauvegarde : fichiers qui n'ont pas pu y être copiés. */
	backupFailedCount: number,
	/**  Quelques-uns de ces fichiers. */
	backupFailedExamples: string[],
};

/**  Langue de l'interface, telle qu'échangée avec elle. */
export type InterfaceLanguageDto = 
/**  Français. */
"fr" | 
/**  Anglais. */
"en";

/**  Résultat pour un fichier. */
export type ItemResultDto = 
/**  En attente. */
"pending" | 
/**  Fait. */
"done" | 
/**  Introuvable. */
"missing" | 
/**  En échec. */
"failed";

/**  Échec prévu d'une tâche. */
export type JobFailure = 
/**  Le dossier n'existe plus ou n'est pas lisible. */
{ kind: "sourceUnavailable"; 
/**  Dossier concerné. */
path: string } | 
/**  Le chemin désigne un fichier, pas un dossier. */
{ kind: "notAFolder"; 
/**  Chemin concerné. */
path: string } | 
/**
 *  Le dossier est sur une carte mémoire ou un appareil photo : import par
 *  référence refusé.
 */
{ kind: "cameraCard"; 
/**  Dossier concerné. */
path: string } | 
/**  Import par copie : la destination est pleine. */
{ kind: "destinationFull"; 
/**  Dossier concerné. */
path: string } | 
/**
 *  Import par copie : la destination ne peut pas être écrite (droits,
 *  disque débranché...).
 */
{ kind: "destinationUnavailable"; 
/**  Dossier concerné. */
path: string } | 
/**  Le catalogue n'a pas pu être lu ou écrit. */
{ kind: "catalogError" };

/**  Nature d'une tâche et ses paramètres, pour l'affichage. */
export type JobKind = 
/**  Analyse d'un dossier avant import. */
{ kind: "folderAnalysis"; 
/**  Dossier analysé. */
folder: string } | 
/**  Import d'un dossier. */
{ kind: "import"; 
/**  Dossier importé. */
folder: string; 
/**  Vrai pour un import par copie. */
copy: boolean; 
/**  Nom de la carte mémoire importée, que le bilan propose d'éjecter. */
card: string | null } | 
/**  Fabrication des vignettes manquantes. */
{ kind: "thumbnails" } | 
/**  Remplissage du lieu des photos géolocalisées. */
{ kind: "places" } | 
/**  Mise à la corbeille des photos rejetées. */
{ kind: "trash"; 
/**  Nombre de fichiers à placer dans la corbeille. */
count: number } | 
/**  Lecture des métadonnées des fichiers de médias du catalogue. */
{ kind: "fileMetadata"; 
/**  Nombre de médias dont les fichiers sont relus. */
count: number } | 
/**  Recherche des fichiers manquants. */
{ kind: "missingFiles" } | 
/**  Écriture des métadonnées dans les fichiers XMP. */
{ kind: "xmpWrite"; 
/**  Nombre de médias dont le XMP est écrit. */
count: number; 
/**
 *  Écriture automatique, après des modifications :
 *  discrète.
 */
automatic: boolean } | 
/**  Ajout des photos traitées par un éditeur externe. */
{ kind: "editedVersions"; 
/**  Fichiers reconnus. */
count: number };

/**  Résultat d'une tâche terminée avec succès. */
export type JobResult = 
/**  Résultat d'une analyse de dossier. */
{ kind: "folderAnalysis"; 
/**  Chiffres clés. */
summary: FolderAnalysisSummary } | 
/**  Bilan d'un import. */
{ kind: "import"; 
/**  Chiffres clés. */
summary: ImportSummary } | 
/**  Bilan d'une fabrication de vignettes. */
{ kind: "thumbnails"; 
/**  Chiffres clés. */
summary: ThumbnailsSummary } | 
/**  Bilan d'un remplissage des lieux. */
{ kind: "places"; 
/**  Chiffres clés. */
summary: PlacesSummary } | 
/**  Bilan d'une mise à la corbeille. */
{ kind: "trash"; 
/**  Chiffres clés. */
summary: TrashSummary } | 
/**  Ce que la lecture des métadonnées des fichiers compléterait. */
{ kind: "fileMetadata"; 
/**  Chiffres clés. */
summary: FileMetadataSummary } | 
/**  Bilan d'une recherche des fichiers manquants. */
{ kind: "missingFiles"; 
/**  Chiffres clés. */
summary: MissingSummary } | 
/**  Bilan d'une écriture des XMP. */
{ kind: "xmpWrite"; 
/**  Chiffres clés. */
summary: XmpWriteSummary } | 
/**  Photos traitées ajoutées au catalogue. */
{ kind: "editedVersions"; 
/**  Chiffres clés. */
summary: EditedVersionsSummary };

/**  Mise à jour d'une tâche, envoyée à l'interface. */
export type JobUpdate = {
	/**  Identifiant de la tâche. */
	id: number,
	/**  Nature de la tâche. */
	kind: JobKind,
	/**  État actuel. */
	status: JobUpdateStatus,
};

/**  État d'une tâche, tel que reçu par l'interface. */
export type JobUpdateStatus = 
/**  En cours. */
{ status: "running"; 
/**  Nombre d'éléments traités. */
progress: number; 
/**  Nombre total d'éléments à traiter, s'il est connu. */
total: number | null } | 
/**  Terminée avec succès. */
{ status: "completed"; 
/**
 *  Résultat (en boîte : un bilan d'import est bien plus gros que les
 *  autres états).
 */
result: JobResult } | 
/**  Terminée sur une erreur prévue. */
{ status: "failed"; 
/**  Cause. */
failure: JobFailure } | 
/**  Annulée par l'utilisateur. */
{ status: "cancelled" } | 
/**  Interrompue par une erreur interne. */
{ status: "crashed" };

