"endsWith";

/**
 *  Filtre mémorisé d'une source : les onglets ouverts et les critères (les
 *  colonnes du filtre Métadonnées restent communes à toutes les sources).
 */
export type SourceFilterContent = {
	/**  Onglets ouverts. */
	tabs: GridFilterTab[],
	/**  Critères des filtres. */
	filter: GridFilter,
};

/**  Changement refusé. */
export type StackFailure = 
/**  Moins de deux photos. */
{ kind: "tooFew" } | 
/**  Photos de plusieurs dossiers. */
{ kind: "severalFolders" } | 
/**  Aucune photo dans une pile. */
{ kind: "notStacked" } | 
/**  Rien à empiler automatiquement. */
{ kind: "nothingToStack" } | 
/**  Le catalogue n'est pas ouvert, ou n'a pas pu être lu ou écrit. */
{ kind: "catalogUnavailable" };

/**  Changement demandé. */
export type StackOperation = 
/**  Empiler (Cmd+G) : la première photo donne la couverture. */
{ kind: "stack"; 
/**  Photos. */
mediaIds: number[] } | 
/**  Dépiler (Cmd+Maj+G). */
{ kind: "unstack"; 
/**  Photos dont les piles sont défaites. */
mediaIds: number[] } | 
/**  Faire de cette photo la couverture de sa pile. */
{ kind: "setCover"; 
/**  Photo. */
mediaId: number } | 
/**  Retirer ces photos de leur pile. */
{ kind: "remove"; 
/**  Photos. */
mediaIds: number[] } | 
/**
 *  Empiler automatiquement (paires RAW + JPEG, rafales), après
 *  confirmation.
 */
{ kind: "auto"; 
/**  Photos examinées. */
scope: AutoStackScope; 
/**  Façon d'empiler. */
method: AutoStackMethod };

/**  Nature d'un échec au démarrage, avec les informations à montrer. */
export type StartupFailure = 
/**  Dossiers du système introuvables. */
{ kind: "systemDirectories" } | 
/**  Fichier de réglages illisible. */
{ kind: "settingsUnreadable"; 
/**  Fichier de réglages. */
path: string } | 
/**  Dossier de travail absent (disque débranché, dossier déplacé...). */
{ kind: "workspaceUnavailable"; 
/**  Dossier de travail attendu. */
path: string } | 
/**  Dossier de travail impossible à créer. */
{ kind: "workspaceCreationFailed"; 
/**  Dossier de travail visé. */
path: string } | 
/**  Fichier du catalogue absent du dossier de travail. */
{ kind: "catalogMissing"; 
/**  Emplacement attendu. */
path: string } | 
/**  Catalogue illisible ou endommagé. */
{ kind: "catalogUnreadable"; 
/**  Fichier du catalogue. */
path: string } | 
/**  Le fichier n'est pas un catalogue PicLib. */
{ kind: "notAPicLibCatalog"; 
/**  Fichier concerné. */
path: string } | 
/**  Catalogue créé par une version plus récente de PicLib. */
{ kind: "catalogTooNew"; 
/**  Fichier du catalogue. */
path: string; 
/**  Version du catalogue. */
found: number; 
/**  Version maximale gérée par cette version de PicLib. */
supported: number } | 
/**  Sauvegarde préalable à la mise à jour impossible. */
{ kind: "backupFailed"; 
/**  Sauvegarde ou dossier des sauvegardes concerné. */
path: string } | 
/**  Mise à jour du catalogue en échec. */
{ kind: "migrationFailed"; 
/**  Sauvegarde faite juste avant, s'il y en a une. */
backup: string | null };

/**  Résultat de l'ouverture du catalogue au démarrage. */
export type StartupStatus = 
/**  Le catalogue est ouvert et à jour. */
{ status: "ready"; 
/**  Dossier de travail. */
workspaceDir: string; 
/**  Version de structure du catalogue. */
schemaVersion: number } | 
/**  Le catalogue n'a pas pu être ouvert. */
{ status: "failed"; 
/**  Nature de l'erreur. */
failure: StartupFailure };

/**  Comparaison impossible. */
export type SyncFailure = 
/**  Le dossier n'est plus au catalogue. */
{ kind: "notFound" } | 
/**  Le dossier est introuvable ou illisible sur le disque. */
{ kind: "unreadable" } | 
/**  Le catalogue n'est pas ouvert ou est illisible. */
{ kind: "catalogUnavailable" };

/**  Ce qu'un modèle fait d'un champ. */
export type TemplateFieldDto = {
	/**  Champ. */
	field: MetadataFieldDto,
	/**  Valeur donnée ; `null` : le champ est vidé. */
	value: string | null,
};

/**  Contenu d'un modèle, tel que rempli dans sa fenêtre. */
export type TemplateInputDto = {
	/**  Nom. */
	name: string,
	/**
	 *  Champs à remplir (`value`) ou à vider (`null`) ; les autres ne
	 *  changent pas.
	 */
	fields: TemplateFieldDto[],
	/**  Mots-clés à ajouter, saisis comme dans le panneau Mots-clés. */
	keywords: string,
};

/**  Bilan d'une fabrication de vignettes, pour l'interface. */
export type ThumbnailsSummary = {
	/**  Vignettes fabriquées. */
	generated: number,
	/**  Photos ou vidéos que le système ne sait pas décoder. */
	failed: number,
};

/**  Mise à la corbeille possible, ou pourquoi elle ne l'est pas. */
export type TrashCheckDto = 
/**  Tous les fichiers sont connus du catalogue. */
{ kind: "possible" } | 
/**  Dossier introuvable (disque débranché, dossier déplacé). */
{ kind: "offline" } | 
/**  Un dossier n'a pas pu être lu. */
{ kind: "unreadable" } | 
/**  Des fichiers sont inconnus du catalogue. */
{ kind: "unknownFiles"; 
/**  Les premiers, chemin relatif au dossier supprimé. */
examples: string[]; 
/**  Nombre total. */
count: number };

/**  Échec de « Mettre à la corbeille la copie non modifiée ». */
export type TrashCopyFailure = 
/**  Aucun catalogue n'est ouvert, ou il n'a pas pu être lu. */
{ kind: "catalogUnavailable" } | 
/**  Ce n'est pas une copie `-Modifié`, ou elle a été modifiée depuis. */
{ kind: "notUnmodified" } | 
/**  La tâche de fond n'a pas pu être lancée. */
{ kind: "jobNotStarted" };

/**  Raison pour laquelle la mise à la corbeille n'a pas démarré. */
export type TrashStartFailure = 
/**  Le catalogue n'est pas ouvert ou est illisible. */
{ kind: "catalogUnavailable" } | 
/**  Le système n'a pas pu lancer la tâche de fond. */
{ kind: "jobNotStarted" };

/**  Mise à la corbeille lancée. */
export type TrashStarted = {
	/**  Tâche de fond ; `null` s'il n'y avait aucune photo rejetée. */
	jobId: number | null,
};

/**  Bilan d'une mise à la corbeille, pour l'interface. */
export type TrashSummary = {
	/**  Fichiers placés dans la corbeille. */
	trashed: number,
	/**  Fichiers introuvables, laissés au catalogue. */
	missing: number,
	/**  Fichiers refusés par le système, laissés à leur place. */
	failed: number,
};

/**  Nouvelle valeur d'un attribut de tri. */
export type TriageChange = 
/**  Marqueur (`null` : aucun). */
{ kind: "flag"; 
/**  Nouveau marqueur. */
flag: FlagDto | null } | 
/**  Note. */
{ kind: "rating"; 
/**  Nombre d'étoiles, de 0 à 5. */
stars: number } | 
/**  Étiquette de couleur (`null` : aucune). */
{ kind: "colorLabel"; 
/**  Nouvelle couleur. */
color: ColorLabelDto | null };

/**  Bilan d'une recherche des XMP modifiés ailleurs. */
export type XmpCheckDto = {
	/**
	 *  Fichiers modifiés par un autre logiciel depuis que PicLib les a
	 *  écrits ou lus.
	 */
	changed: number,
	/**  Fichiers disparus (les photos redeviennent « à enregistrer »). */
	removed: number,
};

/**  Raison pour laquelle l'écriture n'a pas démarré. */
export type XmpWriteStartFailure = 
/**  Aucun catalogue n'est ouvert. */
{ kind: "catalogUnavailable" } | 
/**  La tâche de fond n'a pas pu être lancée. */
{ kind: "jobNotStarted" };

/**  Bilan d'une écriture des XMP. */
export type XmpWriteSummary = {
	/**  Fichiers écrits. */
	written: number,
	/**  Fichiers modifiés par un autre logiciel, laissés tels quels. */
	changedElsewhere: number,
	/**  Échecs (photo introuvable, carte mémoire, fichier illisible...). */
	failed: number,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

